from mesh_config import compile_route_profile

def test_service_execution():
    base = {"prefix": "/api", "timeout_ms": 500}
    env = {"timeout_ms": 250}
    prof = compile_route_profile("mesh-1", base, env)
    assert prof["mesh_id"] == "mesh-1"
    assert prof["prefix"] == "/api"
    assert prof["rules"]["timeout_ms"] == 250

def test_header_matcher_merge():
    base = {
        "prefix": "/api",
        "rules": {
            "headers": ["Authorization", "X-Trace-Id"]
        }
    }
    env = {
        "rules": {
            "headers": ["X-Tenant-Id", "Authorization", "X-Trace-Id"]
        }
    }
    prof = compile_route_profile("mesh-1", base, env)
    expected = ["X-Tenant-Id", "Authorization", "X-Trace-Id"]
    assert prof["rules"]["headers"] == expected
